before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
"fmt"
"os"
)

func save(path string) error {
    file, err := os.Create(path)
    if err != nil { return err }
    _, writeErr := file.WriteString("ready")
    closeErr := file.Close()
    if writeErr != nil { return writeErr }
    return closeErr
}
func main() {
    if err := save("notes.txt"); err != nil { fmt.Println("save failed"); return }
    fmt.Println("saved")
}
```

